\begin{definition}[Sum-of-squares polynomial]
    A polynomial $p(x_1, \dots , x_m) \in \R[x_1, \dots , x_m ]$ is a \emph{sum-of-squares polynomial} if we can write $p(x_1, \dots , x_m) = q_1(x_1, \dots , x_m)^2 + \dots + q_k(x_1, \dots , x_m)^2$ for some polynomials $q_1, \dots , q_k \in \R[x_1, \dots , x_m ]$.
\end{definition}

\begin{definition}[Bounded polynomial]
\label{def:bound-polynomial}
\label{def:sos-bounded-polynomial}
    We say a polynomial $p(x_1, \dots , x_m) \in \R[x_1, \dots , x_m ]$ is \emph{$(d,C)$-bounded} if  
    \begin{enumerate}[label=(\alph*)]
        \item $p$ has degree at most $d$, and
        \item for each monomial of degree $d' \leq d$ in $p$, its coefficient has magnitude at most $C/(d'!)$. 
    \end{enumerate} 
    We say $p$ is a \emph{$(k,d,C)$-bounded sum-of-squares polynomial} if $p$ is a sum-of-squares polynomial, $p = q_1^2 + \dots + q_k^2$, and each of the $q_i$'s are $(d,C)$-bounded.
\end{definition}

\begin{claim}[Composition of bounded SoS polynomials]\label{claim:basic-composition-properties}
Let $p_1(x_1, x_2)$ be a $(k_1, d_1, C_1)$-bounded SoS polynomial and $p_2(x_1, x_2)$ be a $(k_2, d_2, C_2)$-bounded SoS polynomial.  Then
\begin{enumerate}[label=(\alph*)]
    \item $p_1 + p_2$ is a $(k_1 + k_2,\,\max(d_1, d_2),\,\max(C_1, C_2))$-bounded SoS polynomial;
    \item $p_1p_2$ is a $(k_1k_2,\,d_1 + d_2,\,(d_1 + d_2+1)2^{d_1 + d_2}C_1C_2)$-bounded SoS polynomial;
    \item For any $t \in [0,1]$, $p_1((1 - t)x_1 + ty_1, (1 - t)x_2+ ty_2) $ is a $(k_1, d_1, C_1)$-bounded SoS polynomial in $x_1,y_1,x_2,y_2$.
\end{enumerate}
\end{claim}

Let $f_1, f_2, \ldots, f_r$ and $g$ be multivariate polynomials in the indeterminates $x \in \R^m$.
Given the constraints $\{f_1 \geq 0, \ldots, f_r \geq 0\}$, a \emph{sum-of-squares proof} of the identity $\{g \geq 0\}$ is a set of polynomials $\{p_S\}_{S \subseteq [r]}$ such that
\begin{equation*}
    g = \sum_{S \subseteq [r]} p^2_S \cdot \prod_{i \in S} f_i.
\end{equation*}
As its name suggests, the existence of such an SoS proof shows that if the constraints $\{f_i \geq 0 \mid i \in [r]\}$ are satisfied, then the identity $g \geq 0$ is also satisfied.
We say that this SoS proof has \emph{degree $\ell$} if for every set $S \subseteq [r]$, the polynomial $p^2_S \Pi_{i \in S} f_i$ has degree at most $\ell$.
If there is a degree-$\ell$ SoS proof that $\{f_i \geq 0 \mid i \in [r]\}$ implies $\{g \geq 0\}$, we write
\begin{equation}
    \{f_i \geq 0 \mid i \in [r]\} \sststile{\ell}{x}\{g \geq 0\}.
\end{equation}

\begin{definition}
    Let $s_{\ell}(x) = \sum_{k = 0}^\ell \frac{x^k}{k!}$ denote the degree-$\ell$ truncation of the Taylor series of $e^x$.    
\end{definition}

\begin{definition}[Iteratively truncated Taylor series]
\label{def:iterative-truncated-taylor-series}
For positive integers $k,\ell$, we define
\[
p_{k,\ell}(x) = s_{2\ell}(x/k) \cdot s_{4\ell}(x/k) \cdots s_{2^{k}\ell}(x/k) \,
\]
to be the product of $k$ geometrically increasing Taylor series truncations.  Next, we define a shifted integral of $p_{k,\ell}(x)$ as follows:
\[
q_{k,\ell}(x) = 1 + \int_{0}^x p_{k,\ell}(y) dy \,.
\]
The degree of $p_{k, \ell}(x)$ and $q_{k, \ell}$ is $(2^{k+1}-1)\ell$ and $(2^{k+1}-1)\ell+1$, respectively.
\end{definition}

\begin{corollary}[Even truncations are non-negative]\label{coro:positive-truncation}
For any $\ell \in \mathbb{N}$, for all $x \in \mathbb{R}$,   $s_{2\ell}(x) \geq 0$.  
\end{corollary}

\begin{corollary}[Bounded coefficient Polynomials]\label{coro:bouned-sos-coeffs1}
Let $\ell$ be a positive integer and $-0.01 \leq c \leq 0.01$ be a real number.  Then, the polynomial
\[
s_{2\ell}(x) + c s_{2\ell -1}(x)
\]
is a $(2^\ell, \ell, 10^\ell)$-bounded SoS polynomial in $x$ (see Definition~\ref{def:sos-bounded-polynomial}).    
\end{corollary}

\begin{claim}\label{claim:sos-integration}
Let $p(x, y , t)$ be a polynomial such that for all $t \in [0,1]$, it is a $(k,d,C)$-bounded SoS polynomial in $x,y$ (after plugging in a real value for $t$).  Then the polynomial 
\[
r(x,y) = \int_{0}^1 p(x,y, t) dt
\]
is a $(3d^2, d, \sqrt{k}C)$-bounded SoS polynomial in $x,y$.
\end{claim}

\begin{lemma}[Relating $q$ to first and second derivative]\label{claim:manip-of-gradient-identity}
Let $k,\ell$ be positive integers.  Let
\[
r(x,y) = 0.5(x - y)(1 + 0.25(x - y)^2) (q_{k,\ell}(x) - q_{k,\ell}(y)) - 0.00025(x - y)^2 ( p_{k,\ell}(x) + p_{k,\ell}(y)) \,.
\]
Let $z = (x + y)/2$ and $a = (x - y)/2$.  We have the equality
\begin{equation}
\label{eqn:expanding-rxy}
\begin{split}
r(x,y) &= \underbrace{ \int_{0}^{1} \Paren{ \Paren{0.998 a^2 + a^4 } p_{k,\ell}(z + ta ) - 0.001a^3 (2-t) p'_{k,\ell}(z + ta) } dt }_{\eqref{eqn:expanding-rxy}.(1)}  \\
& \hspace{0.2in} + \underbrace{ \int_{0}^{1} \Paren{ \Paren{0.998 a^2 + a^4 } p_{k,\ell}(z - ta ) - 0.001a^3 (2-t) p'_{k,\ell}(z - ta) } dt}_{\eqref{eqn:expanding-rxy}.(2)}  
\end{split}
\end{equation}
\end{lemma}


